"""Map implemented teaching to tasks and evidence, without inventing descriptor coverage."""
import json
from pathlib import Path
from build_skills_audio import content
R=Path(__file__).resolve().parents[1];OUT=R/'docs/cefr'
native=json.loads((OUT/'native-source-cards.json').read_text(encoding='utf8'))
report={'schema':1,'scope':'Implemented task map, not an exhaustive CEFR descriptor inventory','languages':{},'unverified':['Language accuracy and teaching sequence for each exact content version','Breadth and level demands against the full CEFR scales','Independent speaking and writing judgements, reviewer agreement and learner trials','Spontaneous interaction with an unpredictable interlocutor','Unprepared extended discourse, varied speakers and real-world transfer'],'cefrCertificateAwarded':False}
for lang in ['lt','es']:
 c=content(lang);rows=[]
 for u in c['units']:
  uid=u['id'];plan=c['learningPlans'][uid];reading=c['readingTransfer'].get(uid);listening=c['listeningTransfer'].get(uid);exchange=c['guidedInteraction'].get(uid)
  rows.append({'id':uid,'band':u.get('band',uid),'theme':u['theme'],'prerequisite':plan['prerequisite'],'sourceUnits':u.get('sourceUnits',[]),'teaching':{'vocabulary':len(c['vocabulary'][uid]),'phrases':len(u['writing']['phrases']),'sourceExpressions':len(c['sourceSupport'][uid]),'grammarBand':plan['band'],'writingModels':sum(k.startswith(uid+'.') for k in c['writingPreparation'])},'skills':{skill:{'goal':goal['goal'],'scale':goal['scale'],'references':goal['referencePages'],'source':goal['source'],'tasks':goal['practiceIds']+goal.get('relatedPracticeIds',[]),'evidence':plan['evidence'][skill]} for skill,goal in plan['outcomes'].items()},'changedSources':{'reading':len(reading['variants']) if reading else 0,'listening':len(listening['variants']) if listening else 0,'recordedBranches':len(exchange['questions']) if exchange else 0},'writtenExchanges':len(c['writtenInteraction'][uid]['exchanges']),'extendedReadingPortfolios':1 if uid in c.get('extendedReading',{}) else 0,'documentTasks':len(c.get('documents',{}).get(uid,{}).get('variants',[])),'formTasks':len(c.get('forms',{}).get(uid,{}).get('variants',[])),'newPresentationAttempts':{'recordings':2,'firstReviewAndRevisedReview':True,'pastCompletionPreserved':True},'reviewPortfolio':True,'languageReview':'pending','descriptorReview':'pending'})
 report['languages'][lang]={'foundationUnits':[{'id':u['id'],'title':u['title'],'cards':len(u['items']),'legacyReviewOnly':u['retired'],'requiredApplication':'a1.'+({'u1':'first-meeting','u21':'small-talk','u3':'food-order'}.get(u['id'],'unit-'+u['id']) if lang=='lt' else 'unit-'+u['id'])} for u in native[lang]['units']],'workshops':rows}
(OUT/'course-evidence-map.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
lines=['# Teaching, tasks and evidence','','The local build contains 80 source-bound foundation applications (including one retired Lithuanian sounds unit available for review) and 60 required A1–C2 workshops across the two languages. The original 48 workshops include separate changed-source checks and guided exchanges; 12 band applications combine two prepared contexts for a new purpose. These counts do not establish a complete CEFR syllabus.','','All six skill families have explicit goals, preparation and evidence routes. Eight required longer reading portfolios connect prepared passages, whole-text questions, purposeful notes and revised source-based briefs in selected B1–C2 units. Twelve required table-reading tasks check two layouts and comparison with prepared messages in selected A1–A2 units. Twelve required practical forms across the two languages teach labels and field formats before original and changed source details are checked. Recordings and writing revisions are self-reviewed; optional reviewer packets preserve actual artifacts and feedback. A named reviewer is not automatically a calibrated assessor.','','| Language | Band | Required workshops | Separate reading/listening sources | Guided branches | Writing models |','| --- | --- | ---: | ---: | ---: | ---: |']
for lang,d in report['languages'].items():
 for band in ['A1','A2','B1','B2','C1','C2']:
  rows=[r for r in d['workshops'] if r['band']==band]
  lines.append(f"| {lang} | {band} | {len(rows)} | {sum(r['changedSources']['reading']+r['changedSources']['listening'] for r in rows)} | {sum(r['changedSources']['recordedBranches'] for r in rows)} | {sum(r['teaching']['writingModels'] for r in rows)} |")
lines+=['','## Evidence still needed','']+['- '+s for s in report['unverified']]+['','The [complete task map](course-evidence-map.json) includes every implemented goal, named scale, source page, teaching count, task ID and evidence type. The [review books](review/README.md) contain the actual sources and keys. No learner records are used.']
(OUT/'COURSE-EVIDENCE-MAP.md').write_text('\n'.join(lines)+'\n',encoding='utf8');print('Mapped 80 foundation applications and 60 required workshops; review gaps remain explicit.')
